verus! {

    /// Given a positive integer `n` representing the perimeter of a rectangle with integer
    /// side lengths, returns the number of distinct non‐square rectangles (unordered pairs
    /// of side lengths `a < b`) whose perimeter is exactly `n`.
    ///
    /// Ensures:
    /// 1. If `n` is odd, the result is 0.
    /// 2. If `n` is even and `n % 4 == 2`, the result is `n / 4`.
    /// 3. If `n` is divisible by 4, the result is `n / 4 - 1`.
    fn solve(n: i8) -> (result: i8)
        requires
            n > 0,
        ensures
            if n % 2 != 0 {
                result == 0
            } else if n % 4 == 2 {
                result == n / 4
            } else {
                // n % 4 == 0
                result == n / 4 - 1
            }
    {
        // If the perimeter is odd, no integer‐sided rectangle can have that perimeter.
        if n % 2 != 0 {
            return 0;
        }

        // Otherwise the sum of the two sides must be n/2.
        let half = n / 2;

        // Count the number of positive integer pairs (a, b) with a < b and a + b = half.
        // One shows algebraically that this count is floor((half - 1) / 2).
        let result = (half - 1) / 2;
        result
    }
}